import numpy as np, wave
sr=44100
w=wave.open('work/leadtest2.wav'); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
mono=(d[0::2]+d[1::2])/2
seg=mono[int(0.1*sr):int(0.5*sr)]
Z=np.fft.rfft(seg*np.hanning(len(seg)),64*len(seg)); f=np.fft.rfftfreq(64*len(seg),1/sr)
sp=np.abs(Z)
# find ALL local maxima above 5% of max
mx=sp.max()
peaks=[]
for k in range(2,len(sp)-2):
    if sp[k]>sp[k-1] and sp[k]>=sp[k+1] and sp[k]>0.05*mx and f[k]<5000:
        peaks.append((f[k],sp[k]/mx))
# merge close
merged=[]
for fq,mg in peaks:
    if merged and fq-merged[-1][0]<15: 
        if mg>merged[-1][1]: merged[-1]=(fq,mg)
    else: merged.append((fq,mg))
print('spectral peaks:')
for fq,mg in merged[:30]:
    print(f'  {fq:8.2f}  {mg:.3f}')
""}

